#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GameMode {
    Menu,
    Playing,
    End,
}

#[derive(Debug)]
pub struct State {
    pub mode: GameMode,
}

impl State {
    pub fn new() -> Self {
        Self { mode: GameMode::Menu }
    }
    pub fn restart(&mut self) {
        self.mode = GameMode::Playing;
    }
    pub fn play(&mut self) {
        if self.mode == GameMode::Playing {
            self.mode = GameMode::End;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn menu_to_playing() {
        let mut s = State::new();
        assert_eq!(s.mode, GameMode::Menu);
        s.restart();
        assert_eq!(s.mode, GameMode::Playing);
    }
    #[test]
    fn playing_to_end() {
        let mut s = State::new();
        s.restart();
        s.play();
        assert_eq!(s.mode, GameMode::End);
    }
    #[test]
    fn end_to_playing() {
        let mut s = State::new();
        s.restart();
        s.play();
        assert_eq!(s.mode, GameMode::End);
        s.restart();
        assert_eq!(s.mode, GameMode::Playing);
    }
}

