pub struct Rng {
    state: u64,
}

impl Rng {
    pub fn new(seed: u64) -> Self {
        Self { state: seed.wrapping_add(0x9E3779B97F4A7C15) }
    }
    pub fn range(&mut self, lo: i32, hi: i32) -> i32 {
        self.state = self.state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let span = (hi - lo) as u64;
        lo + ((self.state >> 33) % span) as i32
    }
}

pub const W: usize = 20;
pub const H: usize = 20;
pub const STAGGER_DISTANCE: usize = 400;

pub fn build_map(seed: u64) -> Vec<bool> {
    let mut map = vec![false; W * H];
    let mut rng = Rng::new(seed);
    let mut x = (W / 2) as i32;
    let mut y = (H / 2) as i32;
    for _ in 0..STAGGER_DISTANCE {
        let idx = (y as usize) * W + (x as usize);
        map[idx] = true;
        match rng.range(0, 4) {
            0 => x = (x + 1).min((W - 2) as i32),
            1 => x = (x - 1).max(1),
            2 => y = (y + 1).min((H - 2) as i32),
            _ => y = (y - 1).max(1),
        }
    }
    map
}

pub fn floor_connected(map: &[bool]) -> bool {
    let total = map.iter().filter(|&&b| b).count();
    if total == 0 {
        return false;
    }
    let start = map.iter().position(|&b| b).unwrap();
    let mut seen = vec![false; map.len()];
    let mut stack = vec![start];
    seen[start] = true;
    let mut count = 0;
    while let Some(idx) = stack.pop() {
        count += 1;
        let x = (idx % W) as i32;
        let y = (idx / W) as i32;
        for (dx, dy) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let nx = x + dx;
            let ny = y + dy;
            if nx < 0 || ny < 0 || nx >= W as i32 || ny >= H as i32 {
                continue;
            }
            let n = (ny as usize) * W + (nx as usize);
            if map[n] && !seen[n] {
                seen[n] = true;
                stack.push(n);
            }
        }
    }
    count == total
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn seeded_walk_is_deterministic() {
        assert_eq!(build_map(123), build_map(123));
    }
    #[test]
    fn different_seeds_differ() {
        assert_ne!(build_map(1), build_map(2));
    }
    #[test]
    fn all_floor_stays_connected() {
        assert!(floor_connected(&build_map(42)));
    }
}

