#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Point {
    pub x: i32,
    pub y: i32,
}

#[derive(Debug)]
pub struct WantsToMove {
    pub dx: i32,
    pub dy: i32,
}

#[derive(Debug)]
pub struct Map {
    pub width: i32,
    pub height: i32,
}

impl Map {
    pub fn new(width: i32, height: i32) -> Self {
        Self { width, height }
    }
    pub fn can_enter(&self, p: &Point) -> bool {
        if p.x < 0 || p.y < 0 || p.x >= self.width || p.y >= self.height {
            return false;
        }
        if p.x == 0 || p.y == 0 || p.x == self.width - 1 || p.y == self.height - 1 {
            return false;
        }
        true
    }
}

pub fn apply_intent(pos: &mut Point, want: &WantsToMove, map: &Map) {
    let next = Point { x: pos.x + want.dx, y: pos.y + want.dy };
    if map.can_enter(&next) {
        *pos = next;
    }
}

pub fn collisions(player: &Point, enemies: &mut Vec<Point>) {
    enemies.retain(|e| e.x != player.x || e.y != player.y);
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn wall_blocks_intent() {
        let map = Map::new(10, 10);
        let mut p = Point { x: 1, y: 1 };
        apply_intent(&mut p, &WantsToMove { dx: -1, dy: 0 }, &map);
        assert_eq!(p, Point { x: 1, y: 1 });
    }
    #[test]
    fn floor_allows_intent() {
        let map = Map::new(10, 10);
        let mut p = Point { x: 1, y: 1 };
        apply_intent(&mut p, &WantsToMove { dx: 1, dy: 0 }, &map);
        assert_eq!(p, Point { x: 2, y: 1 });
    }
    #[test]
    fn enemy_on_player_is_removed() {
        let player = Point { x: 2, y: 1 };
        let mut enemies = vec![Point { x: 2, y: 1 }, Point { x: 5, y: 5 }];
        collisions(&player, &mut enemies);
        assert_eq!(enemies, vec![Point { x: 5, y: 5 }]);
    }
}

